if isinstance(d,list):
    for p in d[:3]:
        print(json.dumps({k:p.get(k) for k in ['id','name','timeUnit','archived','color','icon','hasExpiration','allowHalfDay','everyoneIncludingNew']}, indent=1))
        print('  keys:', sorted(p.keys()))
""
}

{
  "command": "source /tmp/clockify-openapi-audit/env.sh && python3 -c "
import json
d=json.load(open('/tmp/clockify-openapi-audit/live-policies.json'))
has_exp = sum(1 for p in d if 'hasExpiration' in p)
print('policies:', len(d), '| with hasExpiration key:', has_exp)
# approve shapes
apps = {}
for p in d:
    a = p.get('approve') or {}
    key = (a.get('requiresApproval'), a.get('specificMembers'), a.get('teamManagers'))
    apps[key] = apps.get(key,0)+1
print('approve shapes:', apps)
# pick candidates
for p in d:
    if p['timeUnit']=='DAYS':
        print('DAYS policy:', p['id'], p['name'], 'approve:', p.get('approve'), 'archived:', p['archived'])
        break
for p in d:
    if p['timeUnit']=='HOURS':
        print('HOURS policy:', p['id'], p['name'], 'approve:', p.get('approve'), 'archived:', p['archived'])
        break
# find archived policies
arch=[p for p in d if p['archived']]
print('archived count:', len(arch))
print('users keys sample:', json.dumps(d[0].get('userIds'))[:120])
""
}

